package io.infranexum.core.entitlements;
import io.infranexum.core.contracts.*;import java.nio.file.*;import java.time.*;import java.util.*;import javax.crypto.spec.SecretKeySpec;import io.infranexum.adapters.persistence.jdbc.FileIntegrityProofStore;
public final class ActivationOperationsSmoke {public static void main(String[]a)throws Exception{DomainIdentifier id=new DomainIdentifier(UUID.fromString("0194fd2d-7c5a-7abc-8def-0123456789ab"));InstallationIdentity identity=new InstallationIdentity(id,"v1","a".repeat(64),Instant.parse("2026-01-01T00:00:00Z"));var key=new SecretKeySpec(new byte[32],"HmacSHA256");var guard=new TrustedTimeGuard();var pair=guard.initialize(identity,Instant.parse("2026-01-01T00:00:00Z"),key);Path d=Files.createTempDirectory("inx-proof");try{var store=new FileIntegrityProofStore(d);store.store(pair.independentProof());assert store.load(identity).orElseThrow().equals(pair.independentProof());store.delete(identity);assert store.load(identity).isEmpty();}finally{try(var stream=Files.walk(d)){stream.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception e){throw new RuntimeException(e);}});}}System.out.println("activation-operations-smoke: ok");}}
